// src/protocol.ts
import { z } from "zod";
var clientMessageSchema = z.discriminatedUnion("type", [
  z.object({ type: z.literal("input"), data: z.string().min(1) }),
  // claim:"attach" marks a fresh client's first autofit after connecting.
  // Opening a session is user intent: the server lets it take the shared size
  // unless someone else typed within the last few seconds, instead of the
  // 60s idle window a background resize needs.
  z.object({
    type: z.literal("resize"),
    cols: z.number().int().min(2),
    rows: z.number().int().min(2),
    claim: z.enum(["attach"]).optional(),
    // A claim carrying user:true came from a deliberate human act (clicking a
    // wall tile, switching to the session) — it wins the election outright.
    // A subsequent typist elsewhere reclaims instantly, so misfires self-heal.
    // Old servers strip the field and fall back to attach-claim semantics.
    user: z.boolean().optional()
  }),
  z.object({ type: z.literal("typing"), active: z.boolean() }),
  z.object({ type: z.literal("toggle_collab"), enabled: z.boolean() }),
  z.object({ type: z.literal("take_control") }),
  z.object({ type: z.literal("release_control") }),
  z.object({ type: z.literal("ping"), t: z.number() }),
  z.object({ type: z.literal("kill_session") })
]);
var presenceClientSchema = z.object({
  id: z.string(),
  name: z.string(),
  color: z.string(),
  typing: z.boolean(),
  lastActive: z.number()
});
var serverMessageSchema = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("hello"),
    clientId: z.string(),
    roomId: z.string(),
    color: z.string(),
    collabMode: z.boolean(),
    controllerId: z.string().nullable(),
    // True when this attach created the room (vs joining an existing session).
    // Optional so older clients keep working.
    created: z.boolean().optional()
  }),
  z.object({
    type: z.literal("presence"),
    clients: z.array(presenceClientSchema)
  }),
  z.object({ type: z.literal("output"), data: z.string() }),
  z.object({
    type: z.literal("snapshot"),
    data: z.string(),
    alternateScreen: z.boolean().optional(),
    cursorHidden: z.boolean().optional(),
    // Whether the remote app has enhanced keyboard reporting on (kitty keyboard
    // protocol / xterm modifyOtherKeys). Lets a reattaching client re-enable it on
    // its real terminal so keys like Shift+Enter keep their distinct encoding.
    keyboardEnhanced: z.boolean().optional(),
    // Whether the remote app requested mouse tracking (?1000/1002/1003) and SGR
    // encoding (?1006). Lets a reattaching client scroll the app with per-line
    // wheel events instead of coarse Page keys.
    mouseReporting: z.boolean().optional(),
    mouseSgr: z.boolean().optional()
  }),
  z.object({ type: z.literal("collab"), enabled: z.boolean(), controllerId: z.string().nullable() }),
  z.object({ type: z.literal("input_rejected"), reason: z.string() }),
  z.object({ type: z.literal("error"), message: z.string() }),
  z.object({
    type: z.literal("session_ended"),
    exitCode: z.number().int().nullable(),
    signal: z.string().nullable(),
    message: z.string(),
    // Display name of the client that killed the session, when ended by an
    // explicit kill_session. Optional so older clients keep working.
    by: z.string().optional()
  }),
  z.object({
    type: z.literal("session_renamed"),
    displayName: z.string()
  }),
  z.object({
    type: z.literal("cwd_changed"),
    cwd: z.string()
  }),
  z.object({ type: z.literal("pong"), t: z.number() }),
  // Broadcast when active user's terminal size should be followed
  z.object({ type: z.literal("active_size"), clientId: z.string(), cols: z.number().int(), rows: z.number().int() })
]);
var parseClientMessage = (payload) => {
  const parsed = JSON.parse(payload);
  return clientMessageSchema.parse(parsed);
};
var safeParseClientMessage = (payload) => {
  try {
    const parsed = JSON.parse(payload);
    const result = clientMessageSchema.safeParse(parsed);
    return result.success ? result.data : null;
  } catch {
    return null;
  }
};
var parseServerMessage = (payload) => {
  const parsed = JSON.parse(payload);
  return serverMessageSchema.parse(parsed);
};
var safeParseServerMessage = (payload) => {
  try {
    const parsed = JSON.parse(payload);
    const result = serverMessageSchema.safeParse(parsed);
    return result.success ? result.data : null;
  } catch {
    return null;
  }
};

// src/colors.ts
var PRESENCE_COLORS = [
  "#e67e22",
  "#1abc9c",
  "#3498db",
  "#e74c3c",
  "#9b59b6",
  "#2ecc71",
  "#f1c40f",
  "#16a085",
  "#d35400",
  "#2980b9"
];
var pickPresenceColor = (index) => {
  return PRESENCE_COLORS[index % PRESENCE_COLORS.length];
};
export {
  PRESENCE_COLORS,
  clientMessageSchema,
  parseClientMessage,
  parseServerMessage,
  pickPresenceColor,
  presenceClientSchema,
  safeParseClientMessage,
  safeParseServerMessage,
  serverMessageSchema
};
